81	@RestController
82	@CrossOrigin(exposedHeaders = "errors, content-type")
83	@RequestMapping("/api")
84	public class OwnerRestControllerV1 implements OwnersApi {
85	
86	    /**
87	     * Pragmatic syntactic check for an email address: a non-empty local part, a single {@code @}, and a
88	     * domain with at least one dot and a two-or-more-letter final label. Whitespace is not permitted.
89	     */
90	    private static final Pattern EMAIL_PATTERN =
91	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@.]{2,}$");
92	
93	    /**
94	     * Domains that supply disposable / throwaway mailboxes. An owner whose email domain matches one of
95	     * these (compared case-insensitively) is rejected. Values are stored lower-cased for comparison.
96	     */
97	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
98	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
99	
100	    /**
101	     * The fixed version tag mixed into every version-2 identifier assigned at creation (the
102	     * {@code memberId}'s region code, the {@code householdId} and the {@code identityKey}). Mixing it in
103	     * makes every version-2 identifier disjoint from its version-1 counterpart, so no value produced under
104	     * version 1 is produced again. It is never mixed into the user-facing {@code locality} or
105	     * {@code timezone}, nor into the owner segment's derived region.
106	     */
107	    private static final String IDENTITY_VERSION_TAG = "V2";
108	
109	    /**
110	     * The schema version stamped onto each structured {@code OWNER_CREATED} audit event. Version 2 adds the
111	     * {@code schemaVersion} field and carries the version-2 {@code memberId} as the primary identifier.
112	     */
113	    private static final int AUDIT_EVENT_SCHEMA_VERSION = 2;
114	
115	    /**
116	     * Dedicated audit logger. Successful side-effecting operations (such as creating an owner) emit a
117	     * line here so audit trails can be captured independently of application logging.
118	     */
119	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
120	
121	    /**
122	     * Dedicated notification logger. A newly created owner enqueues a welcome notification by emitting a
123	     * line here carrying the owner id and the assigned member id, so notification side-effects can be
124	     * captured independently of application and audit logging.
125	     */
126	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
127	
128	    /**
129	     * Monotonically increasing sequence number stamped onto each structured {@code OWNER_CREATED} event.
130	     * Shared across all creates so the events can be totally ordered independently of timestamps.
131	     */
132	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
133	
134	    /**
135	     * Serializes structured audit events to compact JSON. Configured once and reused; it is thread-safe.
136	     */
137	    private static final ObjectMapper AUDIT_EVENT_MAPPER = JsonMapper.builder().build();
138	
139	    /**
140	     * The request header carrying a client-supplied idempotency key for the create endpoint. When a create
141	     * repeats with a key already seen, the originally created owner is returned instead of a duplicate.
142	     */
143	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
144	
145	    /**
146	     * Remembers the id of the owner originally created for each seen {@code Idempotency-Key}. A repeated
147	     * create carrying an already-seen key is answered from this map with the original owner rather than
148	     * creating a duplicate.
149	     */
150	    private static final Map<String, Integer> IDEMPOTENT_CREATES = new ConcurrentHashMap<>();
