199	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
200	    @Override
201	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
202	        String idempotencyKey = idempotencyKey();
203	        if (idempotencyKey != null) {
204	            Integer existingId = IDEMPOTENT_CREATES.get(idempotencyKey);
205	            if (existingId != null) {
206	                Owner existing = this.clinicService.findOwnerById(existingId);
207	                if (existing != null) {
208	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
209	                }
210	            }
211	        }
212	        rejectMissingOrBlankFields(ownerFieldsDto);
213	        HttpHeaders headers = new HttpHeaders();
214	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
215	        applyAddress(owner);
216	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
217	        owner.setEmail(normalizeEmail(owner.getEmail()));
218	        validatePostcode(owner.getPostcode(), owner.getCity());
219	        rejectFutureRegistrationDate(owner.getRegistrationDate());
220	        if (owner.getRegistrationDate() == null) {
221	            owner.setRegistrationDate(LocalDate.now());
222	        }
223	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
224	        rejectDailyLimitReached(owner.getRegistrationDate());
225	        rejectCityAtCapacity(owner.getCity());
226	        owner.setHouseholdId(computeHouseholdId(owner));
227	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
228	        rejectDuplicateIdentity(owner);
229	        assignPossibleDuplicate(owner, sharesHousehold);
230	        owner.setMemberId(generateMemberId(owner));
231	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
232	        owner.setHouseholdSize(countHouseholdSize(owner.getHouseholdId()));
233	        owner.setMembershipLevel(computeMembershipLevel(owner));
234	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
235	        owner.setCapacityWarning(isCityApproachingCapacity(owner.getCity()));
236	        this.clinicService.saveOwner(owner);
237	        if (idempotencyKey != null) {
238	            IDEMPOTENT_CREATES.put(idempotencyKey, owner.getId());
239	        }
240	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
241	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
242	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
243	        emitOwnerCreatedEvent(owner, ownerDto);
244	        enqueueWelcomeNotification(owner);
245	        headers.setLocation(UriComponentsBuilder.newInstance()
246	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
247	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
248	    }
