345	    /**
346	     * Emits an immutable structured {@code OWNER_CREATED} event to the {@code AUDIT} logger, alongside the
347	     * human-readable audit line. The event is a schema-version-2 JSON object
348	     * {@code {schemaVersion, seq, ownerId, memberId, membershipLevel, event}} where {@code schemaVersion}
349	     * is {@value #AUDIT_EVENT_SCHEMA_VERSION} and {@code seq} is a process-wide, monotonically increasing
350	     * sequence number across all creates.
351	     *
352	     * <p>The {@code memberId} field carries the owner's <em>current primary identifier</em> — see
353	     * {@link #primaryIdentifier(Owner)} — which is now the version-2 unified member id.
354	     *
355	     * @param owner    the freshly persisted owner
356	     * @param ownerDto its DTO projection, used for the derived membership level
357	     */
358	    private void emitOwnerCreatedEvent(Owner owner, OwnerDto ownerDto) {
359	        Map<String, Object> event = new LinkedHashMap<>();
360	        event.put("schemaVersion", AUDIT_EVENT_SCHEMA_VERSION);
361	        event.put("seq", OWNER_CREATED_SEQUENCE.incrementAndGet());
362	        event.put("ownerId", owner.getId());
363	        event.put("memberId", primaryIdentifier(owner));
364	        event.put("membershipLevel", ownerDto.getMembershipLevel());
365	        event.put("event", "OWNER_CREATED");
366	        AUDIT.info(AUDIT_EVENT_MAPPER.writeValueAsString(event));
367	    }
368	
369	    /**
370	     * Enqueues a welcome notification for a freshly created owner by emitting a line to the {@code NOTIFY}
371	     * logger carrying the owner id and the assigned member id. Downstream notification delivery consumes
372	     * this signal; capturing the logger lets the side-effect be asserted without an implementation hook.
373	     *
374	     * @param owner the freshly persisted owner
375	     */
376	    private void enqueueWelcomeNotification(Owner owner) {
377	        NOTIFY.info("welcome notification enqueued ownerId={} memberId={}",
378	            owner.getId(), owner.getMemberId());
379	    }
380	
381	    /**
382	     * Returns the owner's current primary identifier, which structured audit events must carry. This is the
383	     * single point that decides which field is primary: the unified {@code memberId}.
384	     *
385	     * @param owner the owner whose primary identifier is required
386	     * @return the current primary identifier
387	     */
388	    private String primaryIdentifier(Owner owner) {
389	        return owner.getMemberId();
390	    }
391	
392	    /**
393	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
394	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
395	     *
396	     * @param fields the submitted owner fields
397	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
398	     *                                        {@code null} or blank, or if the owner supplies no address
399	     *                                        in either form (a blank structured {@code addressLine1} and a
400	     *                                        blank flat {@code address}, each measured after normalization)
401	     */
402	    /**
403	     * Reads the client-supplied {@code Idempotency-Key} header for the current create request, if any.
404	     *
405	     * @return the trimmed idempotency key, or {@code null} when the header is absent or blank
406	     */
407	    private String idempotencyKey() {
408	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
409	        if (key == null || key.isBlank()) {
410	            return null;
411	        }
412	        return key.strip();
413	    }
414	
415	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
416	        List<String> missing = new ArrayList<>();
417	        if (isBlank(fields.getFirstName())) {
418	            missing.add("firstName");
419	        }
420	        if (isBlank(fields.getLastName())) {
421	            missing.add("lastName");
422	        }
423	        boolean hasStructuredAddress = !isBlank(normalizeAddress(fields.getAddressLine1()));
424	        boolean hasFlatAddress = !isBlank(normalizeAddress(fields.getAddress()));
425	        if (!hasStructuredAddress && !hasFlatAddress) {
426	            missing.add("address");
427	        }
428	        if (isBlank(fields.getCity())) {
429	            missing.add("city");
430	        }
431	        if (isBlank(fields.getTelephone())) {
432	            missing.add("telephone");
433	        }
434	        if (!missing.isEmpty()) {
435	            throw new RequiredFieldsMissingException(missing);
436	        }
437	    }
438	
439	    private boolean isBlank(String value) {
440	        return value == null || value.isBlank();
441	    }
442	
443	    /**
444	     * Inclusive 4-digit postcode ranges permitted per city region, keyed by the region derived from the
445	     * city via {@link OwnerLocality}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region absent from
446	     * this table (i.e. {@code "UNKNOWN"}) imposes no range constraint, so any 4-digit postcode is accepted.
447	     */
448	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
449	        "NSW", new int[] {2000, 2099},
450	        "VIC", new int[] {3000, 3099},
451	        "QLD", new int[] {4000, 4099});
452	
453	    /**
454	     * Validates an owner's {@code postcode} when present. Postcode is optional: a {@code null} value is
455	     * accepted and left absent, keeping the create contract backward-compatible. When supplied it must be
456	     * a 4-digit value, and it must fall within the inclusive range for the city's region (NSW 2000-2099,
457	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
458	     *
459	     * @param postcode the submitted postcode, or {@code null} when omitted
460	     * @param city the owner's city, used to derive the region whose range constrains the postcode
461	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for the
462	     *                                  city's region
463	     */
464	    private void validatePostcode(String postcode, String city) {
465	        if (postcode == null) {
466	            return;
467	        }
468	        if (!postcode.matches("[0-9]{4}")) {
469	            throw new InvalidPostcodeException(postcode);
470	        }
471	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.of(city));
472	        if (range == null) {
473	            return;
474	        }
475	        int value = Integer.parseInt(postcode);
476	        if (value < range[0] || value > range[1]) {
477	            throw new InvalidPostcodeException(postcode);
478	        }
479	    }
480	
481	    /**
482	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
483	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
484	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
485	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
486	     * <p>
487	     * Where a per-country rule is defined the national-number length is validated against the country
488	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
489	     * requires exactly 10.
490	     *
491	     * @param telephone the raw telephone value from the request
492	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
493	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
494	     */
495	    private String normalizeTelephone(String telephone) {
496	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
497	        String digits;
498	        if (cleaned.startsWith("+")) {
499	            digits = cleaned.substring(1);
500	        } else {
501	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
502	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
503	            digits = "61" + national;
504	        }
505	        if (!digits.matches("[0-9]{8,15}")) {
506	            throw new InvalidTelephoneException(cleaned);
507	        }
508	        // Validate the national-number length against the country code where a rule is defined.
509	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
510	            throw new InvalidTelephoneException(cleaned);
511	        }
512	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
513	            throw new InvalidTelephoneException(cleaned);
514	        }
515	        return "+" + digits;
516	    }
