545	     * fields. When a non-blank {@code addressLine1} is present, {@code addressLine1} and (when present)
546	     * {@code addressLine2} are normalized in place and the flat {@code address} is set to the composed
547	     * value: the normalized {@code addressLine1}, with a single space and the normalized
548	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the structured
549	     * lines are cleared and the flat {@code address} is normalized on its own, keeping the earlier
550	     * flat-address contract backward-compatible.
551	     *
552	     * @param owner the owner being created, mapped straight from the request
553	     */
554	    private void applyAddress(Owner owner) {
555	        if (!isBlank(owner.getAddressLine1())) {
556	            String line1 = normalizeAddress(owner.getAddressLine1());
