558	            String composed = line1;
559	            if (!isBlank(owner.getAddressLine2())) {
560	                String line2 = normalizeAddress(owner.getAddressLine2());
561	                owner.setAddressLine2(line2);
562	                composed = line1 + " " + line2;
563	            } else {
564	                owner.setAddressLine2(null);
565	            }
566	            owner.setAddress(composed);
567	        } else {
568	            owner.setAddressLine1(null);
