574	    /**
575	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
576	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
577	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
578	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
579	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
580	     *
581	     * @param address the raw address value from the request (may be {@code null})
582	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
583	     */
584	    private String normalizeAddress(String address) {
585	        if (address == null) {
586	            return "";
587	        }
588	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
589	        if (collapsed.isEmpty()) {
590	            return "";
591	        }
592	        String[] tokens = collapsed.split(" ");
593	        StringBuilder sb = new StringBuilder(collapsed.length());
594	        for (int i = 0; i < tokens.length; i++) {
595	            if (i > 0) {
596	                sb.append(' ');
597	            }
598	            sb.append(expandAddressAbbreviation(tokens[i]));
599	        }
600	        return sb.toString();
601	    }
