603	    /**
604	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
605	     * returns the token unchanged when it is not a recognised abbreviation.
606	     *
607	     * @param token an upper-cased whole-word address token
608	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
609	     */
610	    private String expandAddressAbbreviation(String token) {
611	        return switch (token) {
612	            case "ST" -> "STREET";
613	            case "RD" -> "ROAD";
614	            case "AVE" -> "AVENUE";
615	            default -> token;
616	        };
617	    }
