619	    /**
620	     * Builds the unified member id assigned to a newly created owner, formatted
621	     * {@code '<REGION><FY><HASH8><CHK>'} where {@code REGION} is the version-2 region code (see
622	     * {@link #regionCodeV2(Owner)}): the plain region derived from the owner's postcode (falling back to the
623	     * city when the postcode resolves to no known region) with the fixed {@code 'V2'} version tag mixed in,
624	     * so the id is disjoint from every version-1 member id; {@code FY} is the two-digit fiscal year of the
625	     * owner's (business-day-adjusted) {@code registrationDate}; {@code HASH8} is the first 8 upper-cased hex
626	     * characters of the SHA-256 digest of the owner's normalized telephone concatenated with the owner's
627	     * last name; and {@code CHK} is a single Luhn check digit computed over the digits of
628	     * {@code '<REGION><FY><HASH8>'} (e.g. {@code 'NSWV2261A2B3C4D7'}).
629	     * <p>
630	     * Should the computed id collide with an existing owner's {@code memberId}, it is de-duplicated by
631	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not already
632	     * held by any existing owner; the de-duplicated id is returned.
633	     *
634	     * @param owner the owner being created, with normalized telephone, postcode and registration date set
635	     * @return the assigned, collision-free member id
636	     */
637	    private String generateMemberId(Owner owner) {
638	        String region = regionCodeV2(owner);
639	        String fiscalYear = fiscalYearSuffix(owner.getRegistrationDate());
640	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
641	            .substring(0, 8).toUpperCase(Locale.ROOT);
642	        String core = region + fiscalYear + hash8;
643	        String base = core + luhnCheckDigit(core);
644	        Set<String> existing = this.clinicService.findAllOwners().stream()
645	            .map(Owner::getMemberId)
646	            .filter(id -> id != null)
647	            .collect(java.util.stream.Collectors.toSet());
648	        if (!existing.contains(base)) {
649	            return base;
650	        }
651	        int n = 2;
652	        while (existing.contains(base + "-" + n)) {
653	            n++;
654	        }
655	        return base + "-" + n;
656	    }
