658	    /**
659	     * Derives the version-2 region code embedded inside the member id: the plain region derived from the
660	     * owner's postcode (falling back to the city) via {@link OwnerLocality}, with the fixed
661	     * {@link #IDENTITY_VERSION_TAG version tag} appended. The version tag is embedded only here, inside the
662	     * identifier; the user-facing {@code locality} and {@code timezone} and the owner segment's derived
663	     * region continue to use the plain region.
664	     *
665	     * @param owner the owner whose version-2 region code is being derived
666	     * @return the plain region with the {@code 'V2'} version tag appended (e.g. {@code 'NSWV2'})
667	     */
668	    private String regionCodeV2(Owner owner) {
669	        return OwnerLocality.of(owner.getCity(), owner.getPostcode()) + IDENTITY_VERSION_TAG;
670	    }
