672	    /**
673	     * Returns the two-digit fiscal-year suffix ({@code '<YY>'}) for the given date: the last two digits of
674	     * the calendar year in which that date's fiscal year (starting 1 July) begins. This is the same value
675	     * carried by the DTO's {@code fiscalYear} and embedded as the {@code FY} segment of the member id.
676	     *
677	     * @param date the (business-day-adjusted) registration date
678	     * @return the zero-padded two-digit fiscal-year suffix
679	     */
680	    private String fiscalYearSuffix(LocalDate date) {
681	        int year = date.getYear();
682	        int start = date.getMonthValue() >= 7 ? year : year - 1;
683	        return String.format("%02d", start % 100);
684	    }
