686	    /**
687	     * Computes a single Luhn check digit (0-9) over the digits contained in {@code value}. Non-digit
688	     * characters are skipped; the rightmost digit is doubled and every second digit thereafter, digits
689	     * exceeding 9 after doubling have 9 subtracted, and the check digit is {@code (10 - sum % 10) % 10}.
690	     *
691	     * @param value the value whose contained digits are summed
692	     * @return the Luhn check digit (between 0 and 9 inclusive)
693	     */
694	    private int luhnCheckDigit(String value) {
695	        int sum = 0;
696	        boolean dbl = true;
697	        for (int i = value.length() - 1; i >= 0; i--) {
698	            char c = value.charAt(i);
699	            if (c < '0' || c > '9') {
700	                continue;
701	            }
702	            int d = c - '0';
703	            if (dbl) {
704	                d *= 2;
705	                if (d > 9) {
706	                    d -= 9;
707	                }
708	            }
709	            sum += d;
710	            dbl = !dbl;
711	        }
712	        return (10 - (sum % 10)) % 10;
713	    }
