715	    /**
716	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
717	     *
718	     * @param value the value to hash
719	     * @return the 64-character lower-case hex SHA-256 digest
720	     */
721	    private String sha256Hex(String value) {
722	        try {
723	            byte[] digest = MessageDigest.getInstance("SHA-256")
724	                .digest(value.getBytes(StandardCharsets.UTF_8));
725	            StringBuilder sb = new StringBuilder(digest.length * 2);
726	            for (byte b : digest) {
727	                sb.append(String.format("%02x", b));
728	            }
729	            return sb.toString();
730	        } catch (NoSuchAlgorithmException e) {
731	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
732	        }
733	    }
