768	    /**
769	     * Computes the membership level assigned to a newly created owner, applying the household level ceiling.
770	     * The owner's own (uncapped) level cannot exceed one above the current maximum membership level among
771	     * their existing household members, where every level is measured against the household's current size
772	     * (the owner's just-computed {@code householdSize}). When the owner has no existing household member the
773	     * ceiling does not apply and the uncapped level is returned. The count is taken before the new owner is
774	     * persisted, so it excludes the owner being created; the existing members share the deterministic
775	     * {@code householdId} and any soft-deleted owner is ignored.
776	     *
777	     * @param owner the owner being created, with its {@code householdId} and {@code householdSize} already set
778	     * @return the owner's membership level, capped at one above the existing household maximum
779	     */
780	    private Integer computeMembershipLevel(Owner owner) {
781	        Integer householdSize = owner.getHouseholdSize();
782	        Integer ownLevel = this.ownerMapper.membershipLevelForHouseholdSize(owner, householdSize);
783	        String householdId = owner.getHouseholdId();
784	        int maxExisting = this.clinicService.findAllOwners().stream()
785	            .filter(existing -> !isDeleted(existing))
786	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
787	            .mapToInt(existing -> this.ownerMapper.membershipLevelForHouseholdSize(existing, householdSize))
788	            .max()
789	            .orElse(-1);
790	        if (maxExisting < 0) {
791	            return ownLevel;
792	        }
793	        return Math.min(ownLevel, maxExisting + 1);
794	    }
