956	    private void rejectDuplicateIdentity(Owner owner) {
957	        String key = identityKey(owner);
958	        boolean taken = this.clinicService.findAllOwners().stream()
959	            .filter(existing -> !isDeleted(existing))
960	            .anyMatch(existing -> key.equals(identityKey(existing)));
961	        if (taken) {
