966	    /**
967	     * Flags a soft (possible) duplicate on the owner being created. A soft match is an existing owner that,
968	     * while not a hard {@code identityKey} duplicate (that stronger check has already run, so its whole
969	     * identity key differs), shares this owner's last-name {@link #soundex(String) soundex} and exact
970	     * postcode. When at least one such owner exists, {@code possibleDuplicate} is set {@code true} and
971	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match, for
972	     * determinism); otherwise {@code possibleDuplicate} is set {@code false} and no match id is recorded. A
973	     * new owner with no postcode has nothing to match on and is never a possible duplicate.
974	     * <p>
975	     * A declared household member ({@code sharesHousehold}) is never flagged: it is a known household member
976	     * rather than a suspected duplicate.
977	     *
978	     * @param owner the owner being created, with normalized telephone and validated postcode already set
979	     * @param sharesHousehold whether the create declared the owner a household member
980	     */
981	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
982	        Integer matchId = null;
983	        if (!sharesHousehold && owner.getPostcode() != null) {
984	            String key = identityKey(owner);
985	            String soundex = soundex(owner.getLastName());
986	            matchId = this.clinicService.findAllOwners().stream()
987	                .filter(existing -> !isDeleted(existing))
988	                .filter(existing -> soundex.equals(soundex(existing.getLastName()))
989	                    && owner.getPostcode().equals(existing.getPostcode())
990	                    && !key.equals(identityKey(existing)))
