120	    /**
121	     * Computes an owner's membership points as {@link #membershipPoints(Owner)} does, but using the supplied
122	     * {@code householdSize} in place of the owner's stored one when awarding the large-household points. This
123	     * lets a caller evaluate an owner's points against the household's <em>current</em> size (for example when
124	     * computing the new-owner level ceiling) without mutating the owner.
125	     *
126	     * @param owner the owner whose points are being computed
127	     * @param householdSize the household size to measure the large-household points against
128	     * @return the owner's membership points (0 or more) for the given household size
129	     */
130	    protected Integer membershipPoints(Owner owner, Integer householdSize) {
131	        int points = 0;
132	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
133	            points += EMAIL_POINTS;
134	        }
135	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
136	            points += NO_NAMESAKE_POINTS;
137	        }
138	        if (householdSize != null && householdSize >= LARGE_HOUSEHOLD_SIZE) {
139	            points += LARGE_HOUSEHOLD_POINTS;
140	        }
141	        if (tenureFiscalYears(owner) >= TENURE_POINTS_FISCAL_YEARS) {
142	            points += TENURE_POINTS;
