192	    /**
193	     * Computes an owner's tenure as the number of elapsed fiscal years between {@code registrationDate} and
194	     * today: the difference between the fiscal year (starting 1 July) of today and that of the registration
195	     * date. A newly created owner (registered in the current fiscal year) has zero tenure. Owners with no
196	     * {@code registrationDate}, or a registration date in a later fiscal year, are treated as zero tenure.
197	     *
198	     * @param owner the owner whose tenure is being computed
199	     * @return the owner's tenure in elapsed fiscal years, never negative
200	     */
201	    protected long tenureFiscalYears(Owner owner) {
202	        LocalDate registrationDate = owner.getRegistrationDate();
203	        if (registrationDate == null) {
204	            return 0;
205	        }
206	        long years = (long) fiscalYearStart(LocalDate.now()) - fiscalYearStart(registrationDate);
207	        return Math.max(years, 0);
208	    }
