318	    /**
319	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
320	     *
321	     * @param value the value to hash
322	     * @return the 64-character lower-case hex SHA-256 digest
323	     */
324	    private String sha256Hex(String value) {
325	        try {
326	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
327	            StringBuilder sb = new StringBuilder(digest.length * 2);
328	            for (byte b : digest) {
329	                sb.append(String.format("%02x", b));
330	            }
331	            return sb.toString();
332	        }
333	        catch (NoSuchAlgorithmException e) {
334	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
335	        }
336	    }
