338	    /**
339	     * Computes the American Soundex code of the given value: the retained (upper-cased) first letter
340	     * followed by three digits derived from the remaining consonants, right-padded with zeros or truncated
341	     * to length four. Non-letters are ignored; adjacent letters mapping to the same digit are coded once
342	     * (bridged across {@code 'H'}/{@code 'W'}), and vowels reset the run. A {@code null} or letter-free
343	     * value yields an empty string. This matches the create endpoint's soundex so identity keys agree.
344	     *
345	     * @param value the value (typically a last name) to encode
346	     * @return the four-character Soundex code, or an empty string when there are no letters
347	     */
348	    private String soundex(String value) {
349	        if (value == null) {
350	            return "";
351	        }
352	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
353	        if (letters.isEmpty()) {
354	            return "";
355	        }
356	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
357	        char prev = soundexDigit(letters.charAt(0));
358	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
359	            char c = letters.charAt(i);
360	            if (c == 'H' || c == 'W') {
361	                continue;
362	            }
363	            char digit = soundexDigit(c);
364	            if (digit != '0' && digit != prev) {
365	                code.append(digit);
366	            }
367	            prev = digit;
368	        }
369	        while (code.length() < 4) {
370	            code.append('0');
371	        }
372	        return code.toString();
373	    }
374	
375	    private char soundexDigit(char c) {
376	        return switch (c) {
377	            case 'B', 'F', 'P', 'V' -> '1';
378	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
379	            case 'D', 'T' -> '3';
380	            case 'L' -> '4';
381	            case 'M', 'N' -> '5';
382	            case 'R' -> '6';
383	            default -> '0';
384	        };
385	    }
