387	    /**
388	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
389	     * national digits grouped in threes from the left (e.g. {@code '+61412345678'} becomes
390	     * {@code '+61 412 345 678'}). The raw {@code telephone} is left untouched in E.164 form. Values that are
391	     * {@code null} or not in E.164 form (no leading {@code '+'}) are returned unchanged.
392	     * <p>
393	     * The country code is split off using the codes the application recognises: {@code '+1'} (NANP) is a
394	     * single digit and any other number is assumed to carry the default {@code '+61'}-style two-digit code.
395	     *
396	     * @param owner the owner whose telephone is being formatted
397	     * @return the human-formatted telephone, or the raw value when it is {@code null} or not E.164
398	     */
399	    protected String telephoneDisplay(Owner owner) {
400	        String telephone = owner.getTelephone();
401	        if (telephone == null || !telephone.startsWith("+")) {
402	            return telephone;
403	        }
404	        String digits = telephone.substring(1);
405	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
406	        if (digits.length() <= countryCodeLength) {
407	            return telephone;
408	        }
409	        String countryCode = digits.substring(0, countryCodeLength);
410	        String national = digits.substring(countryCodeLength);
411	        StringBuilder grouped = new StringBuilder("+").append(countryCode);
412	        for (int i = 0; i < national.length(); i++) {
413	            if (i % 3 == 0) {
414	                grouped.append(' ');
415	            }
416	            grouped.append(national.charAt(i));
417	        }
418	        return grouped.toString();
419	    }
