493	    /**
494	     * Reports whether an email address is <em>disposable-adjacent</em>: its domain carries a known disposable
495	     * provider's name (see {@link #DISPOSABLE_PROVIDER_LABELS}) as one of its dot-separated labels, without
496	     * being an exact blocklisted domain (those are rejected at creation and never stored). So
497	     * {@code x@mailinator.net} and {@code x@sub.mailinator.com} are disposable-adjacent, while a plain domain
498	     * such as {@code x@example.test} is not. A {@code null} or blank email is never disposable-adjacent.
499	     *
500	     * @param email the owner's stored (already normalized) email, or {@code null} when absent
501	     * @return {@code true} when the email's domain carries a disposable provider label, otherwise {@code false}
502	     */
503	    protected boolean disposableAdjacent(String email) {
504	        if (email == null || email.isBlank()) {
505	            return false;
506	        }
507	        int at = email.lastIndexOf('@');
508	        if (at < 0) {
509	            return false;
510	        }
511	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
512	        for (String label : domain.split("\\.")) {
513	            if (DISPOSABLE_PROVIDER_LABELS.contains(label)) {
514	                return true;
515	            }
516	        }
517	        return false;
518	    }
