56	     * QLD-&gt;Australia/Brisbane. The region is resolved with {@link #of(String, String)}.
57	     *
58	     * @param city the owner's city (may be {@code null})
59	     * @param postcode the owner's postcode (may be {@code null})
60	     * @return the IANA timezone name, or {@code null} when the region is not in the table
61	     */
62	    public static String timezoneOf(String city, String postcode) {
63	        return timezoneOfRegion(of(city, postcode));
64	    }
65	
66	    /**
