68	     * QLD-&gt;Australia/Brisbane.
69	     *
70	     * @param region the canonical region string (may be {@code null})
71	     * @return the IANA timezone name, or {@code null} when the region is not in the table
72	     */
73	    public static String timezoneOfRegion(String region) {
74	        if (region == null) {
75	            return null;
76	        }
77	        return switch (region) {
78	            case "NSW" -> "Australia/Sydney";
79	            case "VIC" -> "Australia/Melbourne";
80	            case "QLD" -> "Australia/Brisbane";
81	            default -> null;
82	        };
83	    }
84	
85	    /**
86	     * Resolves a region from a postcode range: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
87	     *
88	     * @param postcode the owner's postcode (may be {@code null})
89	     * @return the region string, or {@code null} when the postcode is absent, not a 4-digit value, or
90	     *         falls in no known range
91	     */
92	    private static String fromPostcode(String postcode) {
93	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
94	            return null;
95	        }
96	        int value = Integer.parseInt(postcode);
97	        if (value >= 2000 && value <= 2099) {
98	            return "NSW";
99	        }
100	        if (value >= 3000 && value <= 3099) {
101	            return "VIC";
102	        }
103	        if (value >= 4000 && value <= 4099) {
104	            return "QLD";
